--------------------------------------------------------------------------------
-- TRIGGER TESTS (GENERATED BY CLAUDE)
-- Run after triggers.sql. Everything is rolled back at the end.
--
-- Each test case runs in its own subtransaction via pg_temp.expect():
--   1. Constraints are DEFERRED, so the case may pass through inconsistent states.
--   2. SET CONSTRAINTS ALL IMMEDIATE then fires every pending deferred check,
--      exactly as COMMIT would.
--   3. The subtransaction is always rolled back, so cases do not affect each other.
-- Output: NOTICE 'PASS: ...' or NOTICE 'FAIL: ...' per case.
--------------------------------------------------------------------------------

SET client_min_messages TO NOTICE;

CREATE FUNCTION pg_temp.expect(label TEXT, should_succeed BOOLEAN, stmts TEXT)
RETURNS VOID AS $$
BEGIN
    BEGIN
        SET CONSTRAINTS ALL DEFERRED;
        EXECUTE stmts;
        SET CONSTRAINTS ALL IMMEDIATE; -- behaves like COMMIT
        RAISE EXCEPTION USING ERRCODE = 'ZZ000'; -- roll back a successful case
    EXCEPTION
        WHEN SQLSTATE 'ZZ000' THEN
            IF should_succeed THEN
                RAISE NOTICE 'PASS: %', label;
            ELSE
                RAISE NOTICE 'FAIL: % (expected an error, but it was accepted)', label;
            END IF;
        WHEN OTHERS THEN
            IF should_succeed THEN
                RAISE NOTICE 'FAIL: % (unexpected error: %)', label, SQLERRM;
            ELSE
                RAISE NOTICE 'PASS: % (rejected: %)', label, SQLERRM;
            END IF;
    END;
END;
$$ LANGUAGE plpgsql;

--------------------------------------------------------------------------------
-- FIXTURE
-- Yard "Y" (type "Simple", max tier 3) with bays 0..1, rows 0..1, tiers 1..3.
-- Ship 211382280 at berth 1.
-- Initial containers:
--   ADIU0000001 on ship 211382280
--   ADIU0000011 at Y (0, 0, 1)
--   ADIU0000012 at Y (0, 0, 2)   (stacked on ADIU0000011)
--------------------------------------------------------------------------------
INSERT INTO Country (country_name) VALUES ('Singapore');
INSERT INTO City (city_name, country_name) VALUES ('Singapore', 'Singapore');
INSERT INTO Company (company_code, company_name, address, postal_code, city_name, country_name)
VALUES ('ADI', 'Apasaja Distribution International', '1 HarbourFront Ave', '098632', 'Singapore', 'Singapore');

INSERT INTO YardType (type, max_tier_number) VALUES ('Simple', 3);
INSERT INTO Yard (yard_code, type) VALUES ('Y', 'Simple');
INSERT INTO Position (yard_code, bay_number, row_number, tier_number) VALUES
('Y', 0, 0, 1), ('Y', 0, 0, 2), ('Y', 0, 0, 3),
('Y', 0, 1, 1), ('Y', 0, 1, 2), ('Y', 0, 1, 3),
('Y', 1, 0, 1), ('Y', 1, 0, 2), ('Y', 1, 0, 3),
('Y', 1, 1, 1), ('Y', 1, 1, 2), ('Y', 1, 1, 3);

INSERT INTO Berth (berth_code, latitude, longitude) VALUES (1, 1.29662, 103.77643);
INSERT INTO Ship (mmsi, imo, call_sign, ship_name, length, width, berth_code)
VALUES (211382280, 9229843, '5LJY5', 'Vessel A', 150.00, 25.00, 1);

INSERT INTO Container (ISO6346, description, company_code, mmsi)
VALUES ('ADIU0000001', 'On ship', 'ADI', 211382280);
INSERT INTO Container (ISO6346, description, company_code, yard_code, bay_number, row_number, tier_number) VALUES
('ADIU0000011', 'Yard ground', 'ADI', 'Y', 0, 0, 1),
('ADIU0000012', 'Yard stacked', 'ADI', 'Y', 0, 0, 2);

-- The fixture itself must satisfy every constraint.
SET CONSTRAINTS ALL IMMEDIATE;

--------------------------------------------------------------------------------
-- TEST: Trigger 2
-- A container must either be on a ship or in a yard (but not both).
--------------------------------------------------------------------------------

DO $$
BEGIN
	RAISE NOTICE '========== TESTING TRIGGER 2 ==========';
END $$;


SELECT pg_temp.expect('T2.1 insert container on a ship only', TRUE, $sql$
    INSERT INTO Container (ISO6346, description, company_code, mmsi)
    VALUES ('ADIU0000002', '-', 'ADI', 211382280);
$sql$);

SELECT pg_temp.expect('T2.2 insert container in a yard only', TRUE, $sql$
    INSERT INTO Container (ISO6346, description, company_code, yard_code, bay_number, row_number, tier_number)
    VALUES ('ADIU0000002', '-', 'ADI', 'Y', 1, 1, 1);
$sql$);

SELECT pg_temp.expect('T2.3 insert container on a ship AND in a yard', FALSE, $sql$
    INSERT INTO Container (ISO6346, description, company_code, yard_code, bay_number, row_number, tier_number, mmsi)
    VALUES ('ADIU0000002', '-', 'ADI', 'Y', 1, 1, 1, 211382280);
$sql$);

SELECT pg_temp.expect('T2.4 insert container on a ship with a partial yard location', FALSE, $sql$
    INSERT INTO Container (ISO6346, description, company_code, yard_code, mmsi)
    VALUES ('ADIU0000002', '-', 'ADI', 'Y', 211382280);
$sql$);

SELECT pg_temp.expect('T2.5 update ship container to also be in a yard', FALSE, $sql$
    UPDATE Container
    SET yard_code = 'Y', bay_number = 1, row_number = 1, tier_number = 1
    WHERE ISO6346 = 'ADIU0000001';
$sql$);

SELECT pg_temp.expect('T2.6 update yard container to also be on a ship', FALSE, $sql$
    UPDATE Container SET mmsi = 211382280 WHERE ISO6346 = 'ADIU0000012';
$sql$);

SELECT pg_temp.expect('T2.7 move ship container to a yard (one UPDATE)', TRUE, $sql$
    UPDATE Container
    SET mmsi = NULL, yard_code = 'Y', bay_number = 1, row_number = 1, tier_number = 1
    WHERE ISO6346 = 'ADIU0000001';
$sql$);

SELECT pg_temp.expect('T2.8 move yard container to a ship (one UPDATE)', TRUE, $sql$
    UPDATE Container
    SET mmsi = 211382280, yard_code = NULL, bay_number = NULL, row_number = NULL, tier_number = NULL
    WHERE ISO6346 = 'ADIU0000012';
$sql$);

DO $$
BEGIN
	RAISE NOTICE '========== END TESTING TRIGGER 2 ==========';
END $$;

--------------------------------------------------------------------------------
-- TEST: Trigger 4
-- A container in a yard is either on the ground or on top of another container;
-- there are no "floating" containers.
-- Stack at Y (0, 0): tier 1 = ADIU0000011, tier 2 = ADIU0000012, tier 3 empty.
--------------------------------------------------------------------------------

DO $$
BEGIN
	RAISE NOTICE '========== TESTING TRIGGER 4 ==========';
END $$;


-- INSERT
SELECT pg_temp.expect('T4.1 insert container on the ground', TRUE, $sql$
    INSERT INTO Container (ISO6346, description, company_code, yard_code, bay_number, row_number, tier_number)
    VALUES ('ADIU0000002', '-', 'ADI', 'Y', 1, 1, 1);
$sql$);

SELECT pg_temp.expect('T4.2 insert container on top of an existing stack', TRUE, $sql$
    INSERT INTO Container (ISO6346, description, company_code, yard_code, bay_number, row_number, tier_number)
    VALUES ('ADIU0000002', '-', 'ADI', 'Y', 0, 0, 3);
$sql$);

SELECT pg_temp.expect('T4.3 insert floating container on an empty slot (tier 2)', FALSE, $sql$
    INSERT INTO Container (ISO6346, description, company_code, yard_code, bay_number, row_number, tier_number)
    VALUES ('ADIU0000002', '-', 'ADI', 'Y', 0, 1, 2);
$sql$);

SELECT pg_temp.expect('T4.4 insert floating container with a gap (tier 3 on empty slot)', FALSE, $sql$
    INSERT INTO Container (ISO6346, description, company_code, yard_code, bay_number, row_number, tier_number)
    VALUES ('ADIU0000002', '-', 'ADI', 'Y', 1, 0, 3);
$sql$);

SELECT pg_temp.expect('T4.5 insert floating container above a different bay/row stack', FALSE, $sql$
    -- (0, 0) has tiers 1-2, but (1, 1) is empty
    INSERT INTO Container (ISO6346, description, company_code, yard_code, bay_number, row_number, tier_number)
    VALUES ('ADIU0000002', '-', 'ADI', 'Y', 1, 1, 2);
$sql$);

-- Transiently floating, but consistent at commit: must be accepted by a deferred trigger.
SELECT pg_temp.expect('T4.6 insert top container before bottom container in same txn', TRUE, $sql$
    INSERT INTO Container (ISO6346, description, company_code, yard_code, bay_number, row_number, tier_number)
    VALUES ('ADIU0000003', '-', 'ADI', 'Y', 1, 1, 2);
    INSERT INTO Container (ISO6346, description, company_code, yard_code, bay_number, row_number, tier_number)
    VALUES ('ADIU0000002', '-', 'ADI', 'Y', 1, 1, 1);
$sql$);

-- UPDATE
SELECT pg_temp.expect('T4.7 move bottom container to another ground slot', FALSE, $sql$
    -- leaves ADIU0000012 floating at (0, 0, 2)
    UPDATE Container SET bay_number = 1, row_number = 1, tier_number = 1
    WHERE ISO6346 = 'ADIU0000011';
$sql$);

SELECT pg_temp.expect('T4.8 move bottom container onto a ship', FALSE, $sql$
    -- leaves ADIU0000012 floating at (0, 0, 2)
    UPDATE Container
    SET mmsi = 211382280, yard_code = NULL, bay_number = NULL, row_number = NULL, tier_number = NULL
    WHERE ISO6346 = 'ADIU0000011';
$sql$);

SELECT pg_temp.expect('T4.9 lift top container up one tier, leaving a gap', FALSE, $sql$
    UPDATE Container SET tier_number = 3 WHERE ISO6346 = 'ADIU0000012';
$sql$);

SELECT pg_temp.expect('T4.10 move top container to an empty slot at tier 2', FALSE, $sql$
    UPDATE Container SET bay_number = 1, row_number = 1 WHERE ISO6346 = 'ADIU0000012';
$sql$);

SELECT pg_temp.expect('T4.11 move ship container to tier 2 of an empty slot', FALSE, $sql$
    UPDATE Container
    SET mmsi = NULL, yard_code = 'Y', bay_number = 1, row_number = 1, tier_number = 2
    WHERE ISO6346 = 'ADIU0000001';
$sql$);

SELECT pg_temp.expect('T4.12 move top container to the ground of another slot', TRUE, $sql$
    UPDATE Container SET bay_number = 1, row_number = 1, tier_number = 1
    WHERE ISO6346 = 'ADIU0000012';
$sql$);

SELECT pg_temp.expect('T4.13 move ship container onto top of the stack', TRUE, $sql$
    UPDATE Container
    SET mmsi = NULL, yard_code = 'Y', bay_number = 0, row_number = 0, tier_number = 3
    WHERE ISO6346 = 'ADIU0000001';
$sql$);

SELECT pg_temp.expect('T4.14 move a whole stack to another slot', TRUE, $sql$
    UPDATE Container SET bay_number = 1, row_number = 1
    WHERE ISO6346 IN ('ADIU0000011', 'ADIU0000012');
$sql$);

-- Transiently floating, but consistent at commit.
SELECT pg_temp.expect('T4.15 swap bottom container with a ship container in same txn', TRUE, $sql$
    UPDATE Container
    SET mmsi = 211382280, yard_code = NULL, bay_number = NULL, row_number = NULL, tier_number = NULL
    WHERE ISO6346 = 'ADIU0000011';
    UPDATE Container
    SET mmsi = NULL, yard_code = 'Y', bay_number = 0, row_number = 0, tier_number = 1
    WHERE ISO6346 = 'ADIU0000001';
$sql$);

-- DELETE
SELECT pg_temp.expect('T4.16 delete top container', TRUE, $sql$
    DELETE FROM Container WHERE ISO6346 = 'ADIU0000012';
$sql$);

SELECT pg_temp.expect('T4.17 delete whole stack', TRUE, $sql$
    DELETE FROM Container WHERE ISO6346 IN ('ADIU0000011', 'ADIU0000012');
$sql$);

SELECT pg_temp.expect('T4.18 delete bottom container', FALSE, $sql$
    -- leaves ADIU0000012 floating at (0, 0, 2)
    DELETE FROM Container WHERE ISO6346 = 'ADIU0000011';
$sql$);

SELECT pg_temp.expect('T4.19 delete bottom container and replace it in same txn', TRUE, $sql$
    DELETE FROM Container WHERE ISO6346 = 'ADIU0000011';
    INSERT INTO Container (ISO6346, description, company_code, yard_code, bay_number, row_number, tier_number)
    VALUES ('ADIU0000002', '-', 'ADI', 'Y', 0, 0, 1);
$sql$);

SELECT pg_temp.expect('T4.20 delete bottom position (cascades to its container)', FALSE, $sql$
    DELETE FROM Position
    WHERE yard_code = 'Y' AND bay_number = 0 AND row_number = 0 AND tier_number = 1;
$sql$);

DO $$
BEGIN
	RAISE NOTICE '========== END TESTING TRIGGER 4 ==========';
END $$;

ROLLBACK;
